#![allow(unused_imports)]
use verus::prelude::*;

verus! {

    /// flipud: produce a new Vec<f32> containing the elements of `m` in reverse order.
    ///
    /// Post‐condition:
    ///   - The output `res` has the same length as `m`.
    ///   - For every valid index `i`, res[i] == m[m.len() - 1 - i].
    pub fn flipud(m: Vec<f32>) -> Vec<f32>
        ensures |res: &Vec<f32>|
            res.len() == m.len()
            && forall(|i: usize| i < m.len() ==> res.get(i).unwrap() == m.get(m.len() - 1 - i).unwrap())
    {
        let n = m.len();
        // Pre-allocate a vector of capacity n
        let mut result: Vec<f32> = Vec::with_capacity(n);
        let mut i: usize = 0;

        // We will push exactly n elements,
        // each time reading m[n-1-i] and appending it to result.
        while i < n
            invariant i <= n
            invariant result.len() == i
            invariant forall(|j: usize| 
                j < i ==>
                    // Up through i−1, result[j] == m[n−1−j]
                    result.get(j).unwrap() == m.get(n - 1 - j).unwrap()
            )
            decreases n - i
        {
            let v = m.get(n - 1 - i).unwrap();
            result.push(v);
            i += 1;
        }

        // At this point i == n and result.len() == n, and the invariant
        // implies the full postcondition.
        result
    }

}